  1	package shop.web;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import io.javalin.Javalin;
  5	import io.javalin.http.Context;
  6	import java.util.LinkedHashMap;
  7	import java.util.List;
  8	import java.util.Map;
  9	import org.slf4j.Logger;
 10	import org.slf4j.LoggerFactory;
 11	import shop.app.CheckoutService;
 12	import shop.app.OrderService;
 13	import shop.app.QueryService;
 14	import shop.domain.ApiException;
 15	import shop.domain.Json;
 16	import shop.domain.Notification;
 17	import shop.domain.Order;
 18	import shop.domain.OrderItem;
 19	
 20	public final class Api {
 21	    private static final Logger LOG = LoggerFactory.getLogger(Api.class);
 22	
 23	    private final CheckoutService checkout;
 24	    private final OrderService orders;
 25	    private final QueryService queries;
 26	
 27	    public Api(CheckoutService checkout, OrderService orders, QueryService queries) {
 28	        this.checkout = checkout;
 29	        this.orders = orders;
 30	        this.queries = queries;
 31	    }
 32	
 33	    public Javalin create() {
 34	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
 35	
 36	        app.post("/checkout/summary", ctx -> json(ctx, 200, checkout.prepare(body(ctx)).summary()));
 37	        app.post("/orders", ctx -> json(ctx, 201, order(orders.register(body(ctx)))));
 38	        app.get("/orders/{id}", ctx -> json(ctx, 200, order(orders.get(ctx.pathParam("id")))));
 39	        app.post("/orders/{id}/payment", ctx -> {
 40	            OrderService.PaymentResult r = orders.pay(ctx.pathParam("id"), body(ctx));
 41	            if (r.error() != null) {
 42	                error(ctx, 409, r.error());
 43	            } else {
 44	                json(ctx, 200, order(r.order()));
 45	            }
 46	        });
 47	        app.post("/orders/{id}/shipment",
 48	                ctx -> json(ctx, 200, order(orders.ship(ctx.pathParam("id"), body(ctx)))));
 49	        app.post("/orders/{id}/delivery", ctx -> json(ctx, 200, order(orders.deliver(ctx.pathParam("id")))));
 50	        app.post("/orders/{id}/cancellation", ctx -> json(ctx, 200, order(orders.cancel(ctx.pathParam("id")))));
 51	        app.get("/products/{sku}", ctx -> json(ctx, 200, queries.product(ctx.pathParam("sku"))));
 52	        app.get("/customers/{cpf}", ctx -> json(ctx, 200, queries.customer(ctx.pathParam("cpf"))));
 53	        app.get("/customers/{cpf}/notifications", ctx -> json(ctx, 200,
 54	                queries.notifications(ctx.pathParam("cpf")).stream().map(Api::notification).toList()));
 55	        app.post("/notifications/{id}/read",
 56	                ctx -> json(ctx, 200, notification(queries.markRead(ctx.pathParam("id")))));
 57	
 58	        app.error(404, ctx -> {
 59	            if (ctx.result() == null || ctx.result().isEmpty()) {
 60	                error(ctx, 404, "NOT_FOUND");
 61	            }
 62	        });
 63	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code()));
 64	        app.exception(Exception.class, (e, ctx) -> {
 65	            LOG.error("unexpected failure", e);
 66	            error(ctx, 500, "INTERNAL_ERROR");
 67	        });
 68	        return app;
 69	    }
 70	
 71	    private static JsonNode body(Context ctx) {
 72	        return Json.parseLenient(ctx.body());
 73	    }
 74	
 75	    private static void json(Context ctx, int status, Object payload) {
 76	        ctx.status(status).contentType("application/json").result(Json.write(payload));
 77	    }
 78	
 79	    private static void error(Context ctx, int status, String code) {
 80	        json(ctx, status, Map.of("error", code));
 81	    }
 82	
 83	    private static Map<String, Object> order(Order o) {
 84	        Map<String, Object> view = new LinkedHashMap<>();
 85	        view.put("id", o.id());
 86	        view.put("status", o.status());
 87	        view.put("createdAt", o.createdAt().toString());
 88	        view.put("summary", o.summary());
 89	        view.put("items", o.items().stream().map(Api::item).toList());
 90	        view.put("trackingCode", o.trackingCode());
 91	        return view;
 92	    }
 93	
 94	    private static Map<String, Object> item(OrderItem i) {
 95	        Map<String, Object> view = new LinkedHashMap<>();
 96	        view.put("sku", i.sku());
 97	        view.put("quantity", i.quantity());
 98	        return view;
 99	    }
100	
101	    private static Map<String, Object> notification(Notification n) {
102	        Map<String, Object> view = new LinkedHashMap<>();
103	        view.put("id", n.id());
104	        view.put("type", n.type());
105	        view.put("orderId", n.orderId());
106	        view.put("status", n.status());
107	        return view;
108	    }
109	}
110	package shop;
111	
112	import com.zaxxer.hikari.HikariConfig;
113	import com.zaxxer.hikari.HikariDataSource;
114	import java.time.Clock;
115	import java.util.List;
116	import shop.app.CheckoutService;
117	import shop.app.CreditEffect;
118	import shop.app.Notifier;
119	import shop.app.OrderService;
120	import shop.app.PaymentApprovedNoticeEffect;
121	import shop.app.QueryService;
122	import shop.app.TransLogClient;
123	import shop.db.Database;
124	import shop.db.Schema;
125	import shop.domain.CarrierGateway;
126	import shop.domain.Rules;
127	import shop.web.Api;
128	
129	public final class Main {
130	    private Main() {
131	    }
132	
133	    /** Wires the whole service on top of a database. */
134	    public static Api wire(Database db, CarrierGateway carrier, Clock clock) {
135	        Rules rules = Rules.standard(carrier);
136	        CheckoutService checkout = new CheckoutService(db, rules);
137	        Notifier notifier = new Notifier();
138	        OrderService orders = new OrderService(db, checkout, clock, notifier,
139	                List.of(new CreditEffect(), new PaymentApprovedNoticeEffect(notifier)));
140	        return new Api(checkout, orders, new QueryService(db));
141	    }
142	
143	    public static void main(String[] args) throws Exception {
144	        HikariConfig config = new HikariConfig();
145	        config.setJdbcUrl(System.getenv("DB_URL"));
146	        config.setUsername(System.getenv("DB_USER"));
147	        config.setPassword(System.getenv("DB_PASSWORD"));
148	        config.setMaximumPoolSize(10);
149	        config.setInitializationFailTimeout(-1);
150	        HikariDataSource dataSource = new HikariDataSource(config);
151	
152	        initSchemaWithRetry(dataSource);
153	
154	        String port = System.getenv("PORT");
155	        Database db = new Database(dataSource);
156	        wire(db, new TransLogClient(System.getenv("TRANSLOG_URL")), Clock.systemUTC())
157	                .create().start(port == null || port.isBlank() ? 8080 : Integer.parseInt(port.trim()));
158	    }
159	
160	    private static void initSchemaWithRetry(HikariDataSource dataSource) throws Exception {
161	        long deadline = System.currentTimeMillis() + 120_000;
162	        while (true) {
163	            try {
164	                Schema.init(dataSource);
165	                return;
166	            } catch (Exception e) {
167	                if (System.currentTimeMillis() > deadline) {
168	                    throw e;
169	                }
170	                System.err.println("Database not ready, retrying: " + e.getMessage());
171	                Thread.sleep(2000);
172	            }
173	        }
174	    }
175	}
