178	/** A refusal that the API reports as {"error": code} with the given HTTP status. */
179	public class ApiException extends RuntimeException {
180	    private final String code;
181	    private final int status;
182	
183	    public ApiException(String code, int status) {
184	        super(code, null, false, false);
185	        this.code = code;
186	        this.status = status;
187	    }
188	
189	    public static ApiException unprocessable(String code) {
190	        return new ApiException(code, 422);
191	    }
192	
193	    public static ApiException conflict(String code) {
194	        return new ApiException(code, 409);
195	    }
196	
197	    public static ApiException notFound(String code) {
198	        return new ApiException(code, 404);
199	    }
200	
201	    public String code() {
202	        return code;
203	    }
204	
205	    public int status() {
206	        return status;
207	    }
208	}
209	package shop.domain;
