211	import com.fasterxml.jackson.core.JsonProcessingException;
212	import com.fasterxml.jackson.databind.JsonNode;
213	import com.fasterxml.jackson.databind.ObjectMapper;
214	import com.fasterxml.jackson.databind.SerializationFeature;
215	import com.fasterxml.jackson.databind.node.MissingNode;
216	import com.fasterxml.jackson.core.JsonGenerator;
217	
218	public final class Json {
219	    public static final ObjectMapper MAPPER = new ObjectMapper()
220	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
221	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
222	
223	    private Json() {
224	    }
225	
226	    public static String write(Object value) {
227	        try {
228	            return MAPPER.writeValueAsString(value);
229	        } catch (JsonProcessingException e) {
230	            throw new IllegalStateException(e);
231	        }
232	    }
233	
234	    public static <T> T read(String text, Class<T> type) {
235	        try {
236	            return MAPPER.readValue(text, type);
237	        } catch (JsonProcessingException e) {
238	            throw new IllegalStateException(e);
239	        }
240	    }
241	
242	    /** Parses a request body; anything that is not valid JSON becomes a missing node. */
243	    public static JsonNode parseLenient(String text) {
244	        if (text == null || text.isBlank()) {
245	            return MissingNode.getInstance();
246	        }
247	        try {
248	            return MAPPER.readTree(text);
249	        } catch (JsonProcessingException e) {
250	            return MissingNode.getInstance();
251	        }
252	    }
253	}

