204	import java.util.Map;
205	import java.util.UUID;
206	import shop.db.Dao;
207	import shop.db.Database;
208	import shop.domain.ApiException;
209	import shop.domain.NotificationType;
210	import shop.domain.Order;
211	import shop.domain.OrderItem;
212	import shop.domain.OrderLifecycle;
213	import shop.domain.OrderLifecycle.Operation;
214	import shop.domain.OrderStatus;
215	import shop.domain.Product;
216	
217	public final class OrderService {
218	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
219	    private static final String OK = "OK";
220	    private static final String EXPIRED = "ORDER_EXPIRED";
221	    private static final String NO_STOCK = "INSUFFICIENT_STOCK";
222	
223	    /** Result of a payment notice: the order, or the code of a refusal that was nevertheless persisted. */
224	    public record PaymentResult(Order order, String error) {
225	    }
226	
227	    private final Database db;
228	    private final CheckoutService checkout;
229	    private final Clock clock;
230	    private final Notifier notifier;
231	    private final List<PaidOrderEffect> effects;
232	
233	    public OrderService(Database db, CheckoutService checkout, Clock clock, Notifier notifier,
234	                        List<PaidOrderEffect> effects) {
235	        this.db = db;
236	        this.checkout = checkout;
237	        this.clock = clock;
238	        this.notifier = notifier;
239	        this.effects = effects;
240	    }
241	
242	    public Order register(JsonNode body) {
243	        CheckoutService.Checkout c = checkout.prepare(body);
244	        Order order = new Order(UUID.randomUUID().toString(), c.cpf(), c.email(), OrderStatus.AWAITING_PAYMENT,
245	                clock.instant().truncatedTo(ChronoUnit.SECONDS), c.summary(), c.items(), null);
246	        return db.tx(d -> {
247	            d.ensureCustomer(c.cpf(), c.email());
248	            d.insertOrder(order);
249	            return order;
250	        });
251	    }
252	
253	    public Order get(String id) {
254	        return db.tx(d -> d.order(id, false).orElseThrow(() -> ApiException.notFound("ORDER_NOT_FOUND")));
255	    }
256	
257	    public PaymentResult pay(String id, JsonNode body) {
258	        return db.tx(d -> {
259	            Order order = lock(d, id);
260	            String transactionId = CheckoutService.text(body.path("transactionId"));
261	            Instant paidAt = parseInstant(body.path("paidAt"));
262	            if (transactionId == null || paidAt == null) {
263	                throw ApiException.unprocessable("INVALID_ORDER");
264	            }
265	            var previous = d.paymentOutcome(id, transactionId);
266	            if (previous.isPresent()) {
267	                return result(order, previous.get());
268	            }
269	            OrderLifecycle.require(order.status(), Operation.PAY);
270	
271	            if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
272	                return refuse(d, order, transactionId, EXPIRED);
273	            }
274	            Map<String, Product> products = d.lockProducts(order.items().stream().map(OrderItem::sku).toList());
275	            for (OrderItem item : order.items()) {
276	                Product p = products.get(item.sku());
277	                if (p == null || p.stock() < item.quantity()) {
278	                    return refuse(d, order, transactionId, NO_STOCK);
279	                }
280	            }
281	            for (OrderItem item : order.items()) {
282	                d.adjustStock(item.sku(), -item.quantity());
283	            }
284	            d.updateStatus(id, OrderStatus.PAID);
285	            Order paid = withStatus(order, OrderStatus.PAID);
286	            for (PaidOrderEffect effect : effects) {
287	                effect.onPaid(d, paid);
288	            }
289	            d.recordPaymentOutcome(id, transactionId, OK);
290	            return new PaymentResult(paid, null);
291	        });
292	    }
293	
294	    public Order ship(String id, JsonNode body) {
295	        return db.tx(d -> {
296	            Order order = lock(d, id);
297	            String trackingCode = CheckoutService.text(body.path("trackingCode"));
298	            if (trackingCode == null) {
299	                throw ApiException.unprocessable("INVALID_ORDER");
300	            }
301	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.SHIP);
302	            d.updateStatus(id, next);
303	            d.updateTrackingCode(id, trackingCode);
304	            Order shipped = new Order(order.id(), order.cpf(), order.email(), next, order.createdAt(),
305	                    order.summary(), order.items(), trackingCode);
306	            notifier.notify(d, shipped, NotificationType.ORDER_SHIPPED);
307	            return shipped;
308	        });
309	    }
310	
311	    public Order deliver(String id) {
312	        return db.tx(d -> {
313	            Order order = lock(d, id);
314	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.DELIVER);
315	            d.updateStatus(id, next);
316	            return withStatus(order, next);
317	        });
318	    }
319	
320	    public Order cancel(String id) {
321	        return db.tx(d -> {
322	            Order order = lock(d, id);
323	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.CANCEL);
324	            if (order.status() == OrderStatus.PAID) {
325	                Map<String, Product> locked = d.lockProducts(order.items().stream().map(OrderItem::sku).toList());
326	                for (OrderItem item : order.items()) {
327	                    if (locked.containsKey(item.sku())) {
328	                        d.adjustStock(item.sku(), item.quantity());
329	                    }
330	                }
331	                for (PaidOrderEffect effect : effects) {
332	                    effect.onPaidOrderCancelled(d, order);
333	                }
334	            }
335	            return markCancelled(d, order, next);
336	        });
337	    }
338	
339	    private PaymentResult refuse(Dao d, Order order, String transactionId, String code) throws SQLException {
340	        Order cancelled = markCancelled(d, order, OrderStatus.CANCELLED);
341	        d.recordPaymentOutcome(order.id(), transactionId, code);
342	        return new PaymentResult(cancelled, code);
343	    }
344	
345	    private Order markCancelled(Dao d, Order order, OrderStatus next) throws SQLException {
346	        d.updateStatus(order.id(), next);
347	        Order cancelled = withStatus(order, next);
348	        notifier.notify(d, cancelled, NotificationType.ORDER_CANCELLED);
349	        return cancelled;
350	    }
351	
352	    private static PaymentResult result(Order order, String outcome) {
353	        return OK.equals(outcome) ? new PaymentResult(order, null) : new PaymentResult(order, outcome);
354	    }
355	
356	    private static Order lock(Dao d, String id) throws SQLException {
357	        return d.order(id, true).orElseThrow(() -> ApiException.notFound("ORDER_NOT_FOUND"));
358	    }
359	
360	    private static Order withStatus(Order o, OrderStatus status) {
361	        return new Order(o.id(), o.cpf(), o.email(), status, o.createdAt(), o.summary(), o.items(),
362	                o.trackingCode());
363	    }
364	
365	    private static Instant parseInstant(JsonNode node) {
366	        String text = CheckoutService.text(node);
367	        if (text == null) {
368	            return null;
369	        }
370	        try {
371	            return OffsetDateTime.parse(text).toInstant();
372	        } catch (DateTimeParseException e) {
373	            return null;
374	        }
375	    }
376	}
