 43	
 44	/** Lookup of pluggable business rules by their code. */
 45	public final class Registry<T> {
 46	    private final Map<String, T> byCode = new LinkedHashMap<>();
 47	
 48	    public Registry(Function<T, String> codeOf, Iterable<? extends T> items) {
 49	        for (T item : items) {
 50	            byCode.put(codeOf.apply(item), item);
 51	        }
 52	    }
