 60	import java.math.BigDecimal;
 61	import java.math.RoundingMode;
 62	
 63	public interface ShippingMethod {
 64	    record Request(String zipCode, BigDecimal weightKg, Region region) {
 65	        public int weightGrams() {
 66	            return weightKg.multiply(BigDecimal.valueOf(1000)).setScale(0, RoundingMode.HALF_UP).intValueExact();
 67	        }
 68	    }
 69	
 70	    record Quote(BigDecimal cost, int days) {
 71	    }
 72	
 73	    String code();
 74	
 75	    /** Refuses with SHIPPING_METHOD_UNAVAILABLE or CARRIER_UNAVAILABLE when it cannot serve the order. */
 76	    Quote quote(Request request);
 77	
 78	    /** False when there is no freight at all (e.g. store pickup). */
 79	    default boolean chargesFreight() {
 80	        return true;
 81	    }
 82	
 83	    /** False when the tier's free-shipping perk does not cover this method (third-party courier). */
 84	    default boolean coveredByTierFreeShipping() {
 85	        return true;
 86	    }
 87	
 88	    /** Fixed price and lead time. */
 89	    record Fixed(String code, BigDecimal cost, int days, boolean chargesFreight, boolean coveredByTierFreeShipping,
 90	                 BigDecimal maxWeightKg) implements ShippingMethod {
 91	        @Override
 92	        public Quote quote(Request request) {
 93	            if (maxWeightKg != null && request.weightKg().compareTo(maxWeightKg) > 0) {
 94	                throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
 95	            }
 96	            return new Quote(cost, days);
 97	        }
 98	    }
 99	
100	    /** Priced by an external carrier; the distribution center adds days in some regions. */
101	    record Carrier(String code, CarrierGateway gateway, String service) implements ShippingMethod {
102	        @Override
103	        public Quote quote(Request request) {
104	            CarrierGateway.Quote q;
105	            try {
106	                q = gateway.quote(request.zipCode(), request.weightGrams(), service)
107	                        .orElseThrow(() -> ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
108	            } catch (CarrierGateway.UnavailableException e) {
109	                throw new ApiException("CARRIER_UNAVAILABLE", 503);
110	            }
111	            return new Quote(q.cost(), q.days() + request.region().extraDispatchDays());
112	        }
113	    }
114	}
115	package shop.domain;
116	
117	import java.math.BigDecimal;
118	import java.math.MathContext;
119	
120	public interface PaymentMethod {
121	    record Settlement(BigDecimal finalTotal, BigDecimal installmentAmount) {
122	    }
123	
124	    String code();
125	
126	    boolean acceptsInstallments(int installments);
127	
128	    /** Refuses with PAYMENT_METHOD_UNAVAILABLE when the method cannot be used for this total. */
129	    default void checkAvailable(BigDecimal orderTotal) {
130	    }
131	
132	    Settlement settle(BigDecimal orderTotal, int installments, boolean couponUsed);
133	
134	    record Pix(String code, BigDecimal discountRate) implements PaymentMethod {
135	        @Override
136	        public boolean acceptsInstallments(int n) {
137	            return n == 1;
138	        }
139	
140	        @Override
141	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
142	            BigDecimal discount = couponUsed ? Money.ZERO : Money.round(total.multiply(discountRate));
143	            BigDecimal result = total.subtract(discount);
144	            return new Settlement(result, result);
145	        }
146	    }
147	
148	    record BankSlip(String code, BigDecimal fee, BigDecimal maximumTotal) implements PaymentMethod {
149	        @Override
150	        public boolean acceptsInstallments(int n) {
151	            return n == 1;
152	        }
153	
154	        @Override
155	        public void checkAvailable(BigDecimal total) {
156	            if (total.compareTo(maximumTotal) > 0) {
157	                throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
158	            }
159	        }
160	
161	        @Override
162	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
163	            BigDecimal result = total.add(fee);
164	            return new Settlement(result, result);
165	        }
166	    }
167	
168	    /** Interest-free up to {@code freeUntil} installments, then Price table. */
169	    record CreditCard(String code, int maxInstallments, int freeUntil, BigDecimal monthlyRate)
170	            implements PaymentMethod {
171	        @Override
172	        public boolean acceptsInstallments(int n) {
173	            return n >= 1 && n <= maxInstallments;
174	        }
175	
176	        @Override
177	        public Settlement settle(BigDecimal total, int n, boolean couponUsed) {
178	            if (n <= freeUntil) {
179	                return new Settlement(total, Money.round(total.divide(BigDecimal.valueOf(n), MathContext.DECIMAL128)));
180	            }
181	            BigDecimal growth = BigDecimal.ONE.add(monthlyRate).pow(n, MathContext.DECIMAL128);
182	            // total * i / (1 - (1+i)^-n)  ==  total * i * (1+i)^n / ((1+i)^n - 1)
183	            BigDecimal installment = Money.round(total.multiply(monthlyRate).multiply(growth)
184	                    .divide(growth.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
185	            return new Settlement(installment.multiply(BigDecimal.valueOf(n)), installment);
186	        }
187	    }
188	}
